IF OBJECT_ID('dbo.PolicyAudit','U') IS NOT NULL DROP TABLE dbo.PolicyAudit; IF OBJECT_ID('dbo.Claims','U') IS NOT NULL DROP TABLE dbo.Claims; IF OBJECT_ID('dbo.Policies','U') IS NOT NULL DROP TABLE dbo.Policies; IF OBJECT_ID('dbo.PolicyCustomers','U') IS NOT NULL DROP TABLE dbo.PolicyCustomers; IF OBJECT_ID('dbo.PolicyCommunications','U') IS NOT NULL DROP TABLE dbo.PolicyCommunications;
CREATE TABLE dbo.PolicyCustomers(CustomerID int PRIMARY KEY,CustomerName nvarchar(100),Email nvarchar(150)); CREATE TABLE dbo.Policies(PolicyID int PRIMARY KEY,CustomerID int REFERENCES dbo.PolicyCustomers,AgentID int,DueDate date,BasePremium decimal(10,2),Status varchar(20),NoClaimYears int DEFAULT 0); CREATE TABLE dbo.Claims(ClaimID int IDENTITY PRIMARY KEY,PolicyID int REFERENCES dbo.Policies,ClaimStatus varchar(20)); CREATE TABLE dbo.PolicyAudit(AuditID int IDENTITY PRIMARY KEY,PolicyID int,ActionName varchar(50),Premium decimal(10,2),AuditDate datetime2 DEFAULT SYSDATETIME()); CREATE TABLE dbo.PolicyCommunications(CommunicationID int IDENTITY PRIMARY KEY,CustomerID int,ComplaintText nvarchar(300),Resolved bit DEFAULT 0);
INSERT dbo.PolicyCustomers VALUES(1,'Meera','meera@example.com'),(2,'Arun','arun@example.com'); INSERT dbo.Policies VALUES(201,1,11,DATEADD(day,30,GETDATE()),12000,'Active',3),(202,2,12,DATEADD(day,-10,GETDATE()),9000,'Active',0); INSERT dbo.Claims(PolicyID,ClaimStatus) VALUES(202,'Pending'),(201,'Closed'); INSERT dbo.PolicyCommunications(CustomerID,ComplaintText,Resolved) VALUES(1,'Claim response delay',0),(2,'Premium clarification',1);